def test_comments_and_blank_lines_are_ignored(tmp_path):
    content = """

# leading comment
@attribute series_name string
@frequency yearly

@data
# comment inside the data section
T1:1.0,2.0

"""
    path = _write_tsf(tmp_path, content)

    loaded, metadata = load_tsf_to_dataframe(path)

    assert len(loaded) == 2
    assert loaded["series_value"].tolist() == [1.0, 2.0]
    assert metadata["frequency"] == "yearly"


def test_absent_optional_metadata_defaults_to_none(tmp_path):
    content = """@attribute series_name string
@data
T1:1.0,2.0
"""
    path = _write_tsf(tmp_path, content)

    loaded, metadata = load_tsf_to_dataframe(path)

    assert loaded.index.get_level_values("timestamp").tolist() == [0, 1]
    assert metadata == {
        "frequency": None,
        "forecast_horizon": None,
        "contain_missing_values": None,
        "contain_equal_length": None,
    }


def test_non_integer_horizon_raises_value_error(tmp_path):
    content = """@attribute n string
@horizon not-an-int
@data
T1:1,2
"""
    path = _write_tsf(tmp_path, content)

    with pytest.raises(ValueError, match="invalid literal for int"):
        load_tsf_to_dataframe(path)
