class _DummyModule:
    """Stand-in for the torch modules held by the predictor."""

    def to(self, device):
        self.device = device
        return self


class _RecordingGenerate:
    """Replacement for ``KronosPredictor.generate`` that records its inputs."""

    def __init__(self, output=None):
        self.output = output
        self.calls = []

    def __call__(
        self, x, x_stamp, y_stamp, pred_len, T, top_k, top_p, sample_count, verbose
    ):
        self.calls.append(
            {
                "x": np.array(x),
                "x_stamp": np.array(x_stamp),
                "y_stamp": np.array(y_stamp),
                "pred_len": pred_len,
                "T": T,
                "top_k": top_k,
                "top_p": top_p,
                "sample_count": sample_count,
                "verbose": verbose,
            }
        )
        if self.output is not None:
            expected = (x.shape[0], pred_len, x.shape[2])
            return np.broadcast_to(self.output, expected).astype(np.float32)
        return np.zeros((x.shape[0], pred_len, x.shape[2]), dtype=np.float32)


def _make_predictor(clip=5, recorder=None):
    predictor = KronosPredictor(
        model=_DummyModule(), tokenizer=_DummyModule(), device="cpu", clip=clip
    )
    if recorder is None:
        recorder = _RecordingGenerate()
    predictor.generate = recorder
    return predictor, recorder


